import React, { useEffect, useState, useRef } from 'react';
import { Link, useLocation } from 'react-router-dom';
import { fetchReviews } from '../api/reviewApi';
// Roulette is shown only on its dedicated page; remove from Home
import PostCard from '../components/PostCard';

// 커뮤니티 샘플 데이터 (화장법, 정보, 잡담 등)
const sampleCommunityPosts = [
  {
    _id: 'c001', 
    author: { username: '뷰티마스터' }, 
    title: '🔥 입문자용 데일리 메이크업 순서 총정리!!', 
    text: '메이크업 처음 시작하는 분들 많이 헷갈리시죠?? 제가 순서 정리해드릴겡ㅋㅋ\n\n1️⃣ 스킨케어 (토너→세럼→크림)\n2️⃣ 선크림 (필수!!!)\n3️⃣ 프라이머\n4️⃣ 파운데이션/쿠션\n5️⃣ 컨실러\n6️⃣ 파우더\n7️⃣ 아이브로우\n8️⃣ 아이섀도우\n9️⃣ 아이라이너\n🔟 마스카라\n\n이 순서로 하면 무너짐 없이 하루종일 유지됨ㅋㅋ 궁금한거 있으면 댓글 ㄱㄱ!!', 
    images: [], 
    createdAt: Date.now() - 1000 * 60 * 60 * 3, 
    likes: 892, 
    comments: 156, 
    tags: ['메이크업순서', '입문자', '꿀팁'],
    category: 'tip'
  },
  {
    _id: 'c002', 
    author: { username: '피부과언니' }, 
    title: '피부 타입별 스킨케어 루틴 공유해요~', 
    text: '안녕하세용 피부과 다니면서 배운거 공유할겡ㅋㅋ\n\n💧건성: 수분크림 두껍게 + 오일 마무리\n🔥지성: 가벼운 수분젤 + 논코메도제닉 제품\n🌡️복합성: T존/U존 다르게 케어\n🌸민감성: 저자극 + 진정 성분 위주\n\n그리고 세안 미온수로!! 뜨거운물 ㄴㄴ 피부장벽 무너져요ㅜㅜ', 
    images: [], 
    createdAt: Date.now() - 1000 * 60 * 60 * 8, 
    likes: 567, 
    comments: 89, 
    tags: ['스킨케어', '피부타입', '루틴'],
    category: 'tip'
  },
  {
    _id: 'c003', 
    author: { username: '립덕후' }, 
    title: '요즘 핫한 립 조합 공유!!!!!', 
    text: '요즘 유행하는 립 조합 정리해봤어용ㅋㅋㅋ\n\n1. 롬앤 베어쥬시 + 페리페라 잉크틴트 = 청순 과즙미 뿜뿜\n2. 에스쁘아 노웨어 + 클리오 킬커버 = 고급진 mlbb\n3. 어뮤즈 듀틴트 + 헤라 센슈얼 = 촉촉 유리알 입술\n\n다들 한번 해봐요 찐 예쁨ㅋㅋㅋ 다른 조합 있으면 댓글로 공유해주세용!!', 
    images: [], 
    createdAt: Date.now() - 1000 * 60 * 60 * 15, 
    likes: 445, 
    comments: 78, 
    tags: ['립조합', '립메이크업', '트렌드'],
    category: 'talk'
  },
  {
    _id: 'c004', 
    author: { username: '올영러버' }, 
    title: '올영세일 뭐 사야되나요ㅠㅠ 추천좀!!', 
    text: '다음주 올영세일인데 뭐 사야할지 모르겟어요ㅜㅜ\n\n예산은 5만원 정도고 스킨케어 위주로 사고싶은데 추천좀요!!\n피부타입은 복합성이고 트러블 좀 있어요ㅠ\n\n선크림이랑 클렌징은 있어서 그거 빼고 추천해주시면 감사합니당!!', 
    images: [], 
    createdAt: Date.now() - 1000 * 60 * 60 * 2, 
    likes: 234, 
    comments: 167, 
    tags: ['올영세일', '추천', '질문'],
    category: 'question'
  },
  {
    _id: 'c005', 
    author: { username: '화장초보' }, 
    title: '아이라인 그리는거 너무 어려워요ㅠㅠ', 
    text: '아이라인 매일 그려보는데 왜이렇게 어렵죠...ㅠㅠ\n\n한쪽은 예쁘게 되는데 다른쪽은 항상 이상해요 진짜 미치겠음ㅋㅋㅋㅋ\n\n고수분들 꿀팁 좀 알려주세요ㅜ 펜라이너 쓰는데 추천 제품도 있으면 알려주세용!!', 
    images: [], 
    createdAt: Date.now() - 1000 * 60 * 60 * 6, 
    likes: 189, 
    comments: 134, 
    tags: ['아이라인', '초보', '질문'],
    category: 'question'
  },
  {
    _id: 'c006', 
    author: { username: '겨울맞이' }, 
    title: '건조한 겨울철 꿀피부 만드는 법 🌨️', 
    text: '겨울되니까 피부 건조해서 미치겠죠ㅜㅜ 제가 쓰는 방법 공유할겡!!\n\n1. 클렌징 후 3초 안에 토너 바르기 (수분 날아가기 전에!!)\n2. 에센스 2-3겹 레이어링\n3. 수분크림 + 페이셜오일 섞어바르기\n4. 일주일에 2번 수분팩\n5. 가습기 필수!!\n\n이거 한달 했더니 피부결 ㄹㅇ 좋아졌어요ㅋㅋ 다들 해봐요!!', 
    images: [], 
    createdAt: Date.now() - 1000 * 60 * 60 * 20, 
    likes: 678, 
    comments: 92, 
    tags: ['겨울스킨케어', '건조피부', '꿀팁'],
    category: 'tip'
  },
  {
    _id: 'c007', 
    author: { username: '글로시퀸' }, 
    title: '오늘의 데일리 메이크업 완성💄✨', 
    text: '오늘 출근 메이크업 공유해용ㅋㅋㅋ\n\n베이스는 촉촉하게 쿠션으로 가볍게 올리고 포인트는 립이에용!! 요즘 핫한 코랄핑크 발라봤는데 얼굴 화사해지는거 실화냐구ㅜㅜ\n\n아이메이크업은 브라운 음영으로 자연스럽게~ 아이라이너 꼬리만 살짝 올려서 눈매 살렸어용\n\n다들 오늘 메이크업 어때요?? 같이 공유해봐요!!🥰', 
    images: ['/images/커뮤니티1.jpg'], 
    createdAt: Date.now() - 1000 * 60 * 60 * 4, 
    likes: 823, 
    comments: 145, 
    tags: ['데일리메이크업', '출근룩', 'OOTD'],
    category: 'talk'
  },
  {
    _id: 'c008', 
    author: { username: '뷰티수집가' }, 
    title: '이번달 뷰티 하울 대공개🛍️💕', 
    text: '월급 들어오자마자 질러버린 뷰티템들ㅋㅋㅋㅋ 통장이 텅장됐지만 후회없음!!!\n\n✨ 구매 목록 ✨\n- 샤넬 루쥬 알뤼르 벨벳 익스트림\n- 디올 백스테이지 아이팔레트\n- 에스티로더 더블웨어 파운데이션\n- 조말론 피오니 앤 블러쉬 스웨이드\n\n다들 이중에 써본거 있어요?? 후기 궁금하면 댓글 달아줘요 리뷰 올려드릴겡ㅋㅋ', 
    images: ['/images/커뮤니티2.jpg'], 
    createdAt: Date.now() - 1000 * 60 * 60 * 12, 
    likes: 567, 
    comments: 98, 
    tags: ['하울', '럭셔리뷰티', '신상'],
    category: 'talk'
  },
  {
    _id: 'c009', 
    author: { username: '스킨케어요정' }, 
    title: '트러블 진정시키는 나만의 루틴 공유💚', 
    text: '피부 뒤집어졌을때 제가 쓰는 비상 루틴이에용!!\n\n🌿 1단계: 저자극 클렌저로 부드럽게 세안\n🌿 2단계: 티트리 토너로 진정\n🌿 3단계: 시카 세럼 듬뿍\n🌿 4단계: 마데카 크림으로 마무리\n🌿 +보너스: 스팟패치 붙이고 자기!!\n\n이거 3일만 하면 진짜 가라앉아요ㅜㅜ 트러블 때문에 고민인 분들 해보세용!! 진짜 효과 봄ㅋㅋㅋ', 
    images: ['/images/커뮤니티3.jpg'], 
    createdAt: Date.now() - 1000 * 60 * 60 * 18, 
    likes: 712, 
    comments: 203, 
    tags: ['트러블케어', '진정루틴', '스킨케어'],
    category: 'tip'
  },
];

function Home() {
  const [latest, setLatest] = useState([]);
  const [posts, setPosts] = useState([]);
  const [communityPosts, setCommunityPosts] = useState(sampleCommunityPosts);
  const [postType, setPostType] = useState('community'); // 글쓰기 타입 (커뮤니티 기본)
  const [communityCategory, setCommunityCategory] = useState('all'); // 커뮤니티 카테고리 필터
  const [author, setAuthor] = useState('');
  const [text, setText] = useState('');
  const [files, setFiles] = useState([]); // 다중 파일 지원
  const [dragOver, setDragOver] = useState(false);
  const [mousePos, setMousePos] = useState({ x: 0, y: 0 });
  const fileInputRef = useRef();
  const heroRef = useRef();

  // 마우스 추적 효과
  useEffect(() => {
    const handleMouseMove = (e) => {
      if (heroRef.current) {
        const rect = heroRef.current.getBoundingClientRect();
        setMousePos({
          x: ((e.clientX - rect.left) / rect.width) * 100,
          y: ((e.clientY - rect.top) / rect.height) * 100
        });
      }
    };
    window.addEventListener('mousemove', handleMouseMove);
    return () => window.removeEventListener('mousemove', handleMouseMove);
  }, []);

  useEffect(() => {
    const load = async () => {
      try {
        const res = await fetchReviews({ page: 1, limit: 3 });
        setLatest(res.data);
      } catch (err) {
        console.error('fetch reviews failed', err);
      }
    };
    load();
  }, []);

  const location = useLocation();
  const params = new URLSearchParams(location.search);
  const showReviews = params.get('view') === 'reviews';

  // load posts from localStorage
  useEffect(() => {
    try {
      const raw = localStorage.getItem('blog_posts');
      if (raw) setPosts(JSON.parse(raw));
    } catch (e) { setPosts([]); }
  }, []);

  const savePosts = (list) => {
    try { localStorage.setItem('blog_posts', JSON.stringify(list)); } catch (e) {}
  };

  // 파일 읽기 함수
  const readFileAsDataURL = (file) => new Promise((res, rej) => {
    const reader = new FileReader();
    reader.onload = () => res(reader.result);
    reader.onerror = rej;
    reader.readAsDataURL(file);
  });

  // 파일 처리
  const handleFiles = async (fileList) => {
    const arr = Array.from(fileList).slice(0, 8 - files.length); // 최대 8개
    const processed = await Promise.all(arr.map(async (f) => {
      const dataUrl = await readFileAsDataURL(f);
      const type = f.type.startsWith('video') ? 'video' : 'image';
      return { dataUrl, type, name: f.name };
    }));
    setFiles(prev => [...prev, ...processed]);
  };

  // 드래그앤드롭
  const onDrop = (e) => {
    e.preventDefault();
    setDragOver(false);
    if (e.dataTransfer && e.dataTransfer.files) {
      handleFiles(e.dataTransfer.files);
    }
  };

  const onFileChange = (e) => {
    if (e.target.files) handleFiles(e.target.files);
  };

  const removeFile = (index) => {
    setFiles(prev => prev.filter((_, i) => i !== index));
  };

  // 태그 파싱
  const parseTags = (text) => {
    const tags = new Set();
    const regex = /#([a-zA-Z0-9\u3131-\uD79D_-]+)/g;
    let m;
    while ((m = regex.exec(text))) {
      tags.add(m[1].toLowerCase());
    }
    return Array.from(tags);
  };

  const handleCreatePost = async (e) => {
    e.preventDefault();
    const authorName = author.trim() || '익명';
    const content = text.trim();
    if (!content) return alert('내용을 입력해주세요');
    
    const tags = parseTags(content);
    const images = files.map(f => f.dataUrl);
    
    if (postType === 'review') {
      // 리뷰 작성
      const newReview = { 
        _id: 'r' + Date.now(), 
        author: { username: authorName }, 
        title: content.split('\n')[0].slice(0, 30),
        text: content, 
        images, 
        createdAt: Date.now(), 
        likes: 0,
        comments: 0,
        tags,
        rating: 0
      };
      setReviews(prev => [newReview, ...prev]);
    } else {
      // 커뮤니티 글 작성
      const newPost = { 
        _id: 'c' + Date.now(), 
        author: { username: authorName }, 
        title: content.split('\n')[0].slice(0, 50),
        text: content, 
        images, 
        createdAt: Date.now(), 
        likes: 0,
        comments: 0,
        tags,
        category: 'talk'
      };
      setCommunityPosts(prev => [newPost, ...prev]);
    }
    
    // reset form
    setAuthor('');
    setText('');
    setFiles([]);
  };

  // 커뮤니티 카테고리 필터링
  const filteredCommunityPosts = communityCategory === 'all' 
    ? communityPosts 
    : communityPosts.filter(p => p.category === communityCategory);

  return (
    <div style={{ padding: 20, maxWidth: 1200, margin: '0 auto' }}>
      <header style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 24 }}>
        <div>
          <h1 style={{ margin: 0, fontSize: 24, fontWeight: 800 }}>✨ Review Community</h1>
          <p style={{ color: '#666', margin: '4px 0 0' }}>실제 사람들이 쓰는 생생한 리뷰와 뷰티 정보를 만나보세요.</p>
        </div>
        <div>
          <Link to="/coupons"><button style={{ padding: '12px 20px', borderRadius: 12, background: 'linear-gradient(135deg, #ff4d88, #ff6b9d)', color: '#fff', border: 'none', fontWeight: 600, cursor: 'pointer' }}>🎡 룰렛 참여하기</button></Link>
        </div>
      </header>

      {/* 글쓰기 타입 선택 탭 */}
      <section style={{ marginBottom: 24 }}>
        <div style={{ 
          background: '#fff', 
          borderRadius: 16, 
          padding: '8px',
          marginBottom: 16,
          border: '1px solid #e6eefb',
          display: 'flex',
          gap: 8
        }}>
          <button
            onClick={() => setPostType('review')}
            style={{
              flex: 1,
              padding: '16px 20px',
              borderRadius: 12,
              border: 'none',
              background: postType === 'review' ? 'linear-gradient(135deg, #ff4d88, #ff6b9d)' : 'transparent',
              color: postType === 'review' ? '#fff' : '#666',
              fontWeight: 600,
              fontSize: 14,
              cursor: 'pointer',
              transition: 'all 0.2s ease',
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              gap: 10
            }}
          >
            <span style={{ fontSize: 20 }}>💄</span>
            <div style={{ textAlign: 'left' }}>
              <div style={{ fontWeight: 700 }}>리뷰 작성</div>
              <div style={{ fontSize: 11, fontWeight: 400, opacity: 0.8 }}>제품 사용 후기</div>
            </div>
          </button>
          <button
            onClick={() => setPostType('community')}
            style={{
              flex: 1,
              padding: '16px 20px',
              borderRadius: 12,
              border: 'none',
              background: postType === 'community' ? 'linear-gradient(135deg, #8b5cf6, #a78bfa)' : 'transparent',
              color: postType === 'community' ? '#fff' : '#666',
              fontWeight: 600,
              fontSize: 14,
              cursor: 'pointer',
              transition: 'all 0.2s ease',
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              gap: 10
            }}
          >
            <span style={{ fontSize: 20 }}>💬</span>
            <div style={{ textAlign: 'left' }}>
              <div style={{ fontWeight: 700 }}>커뮤니티 글</div>
              <div style={{ fontSize: 11, fontWeight: 400, opacity: 0.8 }}>화장법, 정보, 잡담</div>
            </div>
          </button>
        </div>

        {/* 글쓰기 가이드 */}
        <div style={{ 
          background: postType === 'review' 
            ? 'linear-gradient(135deg, #fff0f5 0%, #fff 100%)' 
            : 'linear-gradient(135deg, #f5f3ff 0%, #fff 100%)', 
          borderRadius: 16, 
          padding: '16px 20px',
          marginBottom: 16,
          border: postType === 'review' 
            ? '1px solid rgba(255,77,136,0.15)'
            : '1px solid rgba(139,92,246,0.15)',
          display: 'flex',
          alignItems: 'center',
          gap: 16
        }}>
          <div style={{ 
            width: 48, height: 48, 
            background: postType === 'review'
              ? 'linear-gradient(135deg, #ff4d88, #ff8a5c)'
              : 'linear-gradient(135deg, #8b5cf6, #a78bfa)', 
            borderRadius: 12,
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            fontSize: 24
          }}>{postType === 'review' ? '📷' : '✨'}</div>
          <div style={{ flex: 1 }}>
            {postType === 'review' ? (
              <>
                <div style={{ fontWeight: 700, marginBottom: 2 }}>제품 리뷰를 작성해보세요!</div>
                <div style={{ color: '#666', fontSize: 13 }}>제품 사진, 발색샷, 비포/애프터 등을 함께 올려주세요 💄</div>
              </>
            ) : (
              <>
                <div style={{ fontWeight: 700, marginBottom: 2 }}>뷰티 정보를 공유해보세요!</div>
                <div style={{ color: '#666', fontSize: 13 }}>화장법, 꿀팁, 질문, 수다 뭐든 OK! 자유롭게 떠들어요 💬</div>
              </>
            )}
          </div>
          <div style={{ display: 'flex', gap: 8 }}>
            {postType === 'review' ? (
              <>
                <span style={{ background: '#fff', border: '1px solid #e6eefb', padding: '6px 10px', borderRadius: 8, fontSize: 11, color: '#666' }}>📸 제품샷</span>
                <span style={{ background: '#fff', border: '1px solid #e6eefb', padding: '6px 10px', borderRadius: 8, fontSize: 11, color: '#666' }}>💄 발색</span>
              </>
            ) : (
              <>
                <span style={{ background: '#fff', border: '1px solid #e6eefb', padding: '6px 10px', borderRadius: 8, fontSize: 11, color: '#666' }}>💡 꿀팁</span>
                <span style={{ background: '#fff', border: '1px solid #e6eefb', padding: '6px 10px', borderRadius: 8, fontSize: 11, color: '#666' }}>❓ 질문</span>
                <span style={{ background: '#fff', border: '1px solid #e6eefb', padding: '6px 10px', borderRadius: 8, fontSize: 11, color: '#666' }}>💬 수다</span>
              </>
            )}
          </div>
        </div>

        {/* 글쓰기 폼 - Composer 스타일 */}
        <div style={{ 
          background: '#fff', 
          borderRadius: 16, 
          padding: 16,
          border: '1px solid #e6eefb'
        }}>
          <form onSubmit={handleCreatePost}>
            {/* 작성자 + 텍스트 영역 (나란히) */}
            <div style={{ display: 'flex', gap: 12, marginBottom: 12 }}>
              <div style={{ 
                flex: '0 0 140px',
                padding: '12px 16px',
                borderRadius: 10,
                border: '1px solid #e6eefb',
                background: '#fafafa',
                display: 'flex',
                alignItems: 'flex-start'
              }}>
                <input 
                  value={author}
                  onChange={(e) => setAuthor(e.target.value)}
                  placeholder="작성자" 
                  style={{ 
                    width: '100%',
                    border: 'none',
                    background: 'transparent',
                    fontSize: 14,
                    outline: 'none',
                    color: '#333'
                  }} 
                />
              </div>
              <textarea 
                value={text}
                onChange={(e) => setText(e.target.value)}
                placeholder="무슨 생각을 하고 계신가요? #태그를 사용해보세요" 
                style={{ 
                  flex: 1,
                  minHeight: 100, 
                  padding: '12px 16px', 
                  borderRadius: 10, 
                  border: '1px solid #e6eefb',
                  fontSize: 14,
                  lineHeight: 1.6,
                  resize: 'vertical',
                  outline: 'none'
                }} 
              />
            </div>

            {/* 드래그앤드롭 업로드 영역 */}
            <div 
              onDrop={onDrop} 
              onDragOver={(e) => { e.preventDefault(); setDragOver(true); }} 
              onDragLeave={() => setDragOver(false)} 
              onClick={() => fileInputRef.current && fileInputRef.current.click()}
              style={{ 
                border: `2px dashed ${dragOver ? '#ff4d88' : '#e6eefb'}`, 
                padding: 20, 
                borderRadius: 12, 
                marginBottom: 12, 
                textAlign: 'center', 
                background: dragOver ? '#fff5f7' : '#fafafa', 
                cursor: 'pointer',
                transition: 'all 0.2s ease'
              }}
            >
              <div style={{ color: '#666', fontSize: 14 }}>
                이미지/동영상을 드래그하거나 클릭하여 업로드하세요 (최대 8개)
              </div>
              <input 
                ref={fileInputRef} 
                type="file" 
                multiple 
                accept="image/*,video/*" 
                onChange={onFileChange} 
                style={{ display: 'none' }} 
              />
            </div>

            {/* 파일 미리보기 */}
            {files.length > 0 && (
              <div style={{ 
                display: 'grid', 
                gridTemplateColumns: 'repeat(auto-fill, minmax(100px, 1fr))', 
                gap: 8, 
                marginBottom: 12 
              }}>
                {files.map((f, i) => (
                  <div key={i} style={{ position: 'relative' }}>
                    {f.type === 'video' ? (
                      <video src={f.dataUrl} style={{ width: '100%', height: 80, objectFit: 'cover', borderRadius: 8 }} />
                    ) : (
                      <img src={f.dataUrl} alt="" style={{ width: '100%', height: 80, objectFit: 'cover', borderRadius: 8 }} />
                    )}
                    <button 
                      type="button"
                      onClick={() => removeFile(i)}
                      style={{ 
                        position: 'absolute', 
                        top: 4, 
                        right: 4, 
                        width: 20, 
                        height: 20, 
                        borderRadius: '50%', 
                        border: 'none', 
                        background: 'rgba(0,0,0,0.6)', 
                        color: '#fff', 
                        fontSize: 12, 
                        cursor: 'pointer',
                        display: 'flex',
                        alignItems: 'center',
                        justifyContent: 'center'
                      }}
                    >×</button>
                  </div>
                ))}
              </div>
            )}

            {/* 하단 버튼 영역 */}
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
              <div style={{ color: '#999', fontSize: 12 }}>{files.length} files</div>
              <div style={{ display: 'flex', gap: 8 }}>
                <button 
                  type="button" 
                  onClick={() => { setText(''); setFiles([]); setAuthor(''); }}
                  style={{ 
                    padding: '10px 20px', 
                    borderRadius: 10, 
                    border: '1px solid #e6eefb', 
                    background: '#fff',
                    fontSize: 14,
                    cursor: 'pointer'
                  }}
                >
                  초기화
                </button>
                <button 
                  type="submit" 
                  style={{ 
                    padding: '10px 24px', 
                    borderRadius: 10, 
                    background: postType === 'review' 
                      ? 'linear-gradient(135deg, #ff4d88, #ff6b9d)' 
                      : 'linear-gradient(135deg, #8b5cf6, #a78bfa)', 
                    color: '#fff', 
                    border: 'none', 
                    cursor: 'pointer',
                    fontWeight: 600,
                    fontSize: 14
                  }}
                >
                  게시하기
                </button>
              </div>
            </div>
          </form>
        </div>
      </section>

      {/* 🔥 인기 태그 섹션 */}
      <div style={{ 
        background: '#fff', 
        borderRadius: 16, 
        padding: 20, 
        marginBottom: 24,
        border: '1px solid #e6eefb'
      }}>
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 16 }}>
          <h3 style={{ margin: 0, fontSize: 16 }}>🔥 지금 핫한 태그</h3>
          <span style={{ color: '#888', fontSize: 12 }}>실시간 인기</span>
        </div>
        <div style={{ display: 'flex', gap: 10, flexWrap: 'wrap' }}>
          {['겨울스킨케어', '퍼스널컬러', '쉐이딩', '올영세일', '데일리메이크업', '수분크림', '시카크림', '립조합'].map((tag, idx) => (
            <span 
              key={tag} 
              style={{ 
                background: idx < 3 ? 'linear-gradient(135deg, #ff4d88, #ff6b9d)' : '#f3f4f6',
                color: idx < 3 ? '#fff' : '#666',
                padding: '8px 16px', 
                borderRadius: 20, 
                fontSize: 13,
                fontWeight: idx < 3 ? 600 : 400,
                cursor: 'pointer',
                transition: 'all 0.2s ease'
              }}
            >
              {idx < 3 && <span style={{ marginRight: 4 }}>🔥</span>}#{tag}
            </span>
          ))}
        </div>
      </div>

      {/* 💬 커뮤니티 섹션 */}
      <div style={{ marginBottom: 20 }}>
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 16 }}>
          <h3 style={{ margin: 0, fontSize: 18 }}>💬 커뮤니티</h3>
          <div style={{ display: 'flex', gap: 8 }}>
            {[
              { id: 'all', name: '전체', color: '#8b5cf6' },
              { id: 'tip', name: '💡 꿀팁', color: '#16a34a' },
              { id: 'question', name: '❓ 질문', color: '#d97706' },
              { id: 'talk', name: '💬 수다', color: '#8b5cf6' }
            ].map(cat => (
              <button 
                key={cat.id}
                onClick={() => setCommunityCategory(cat.id)}
                style={{ 
                  padding: '6px 14px', 
                  borderRadius: 16, 
                  border: 'none',
                  background: communityCategory === cat.id ? cat.color : '#f3f4f6',
                  color: communityCategory === cat.id ? '#fff' : '#666',
                  fontSize: 12,
                  cursor: 'pointer',
                  fontWeight: communityCategory === cat.id ? 600 : 400
                }}
              >{cat.name}</button>
            ))}
          </div>
        </div>
      </div>

      {/* 커뮤니티 글 목록 */}
      <div style={{ display: 'flex', flexDirection: 'column', gap: 12 }}>
        {filteredCommunityPosts.map(post => (
          <div 
            key={post._id}
            style={{
              background: '#fff',
              borderRadius: 16,
              padding: '20px 24px',
              border: '1px solid #e6eefb',
              cursor: 'pointer',
              transition: 'all 0.2s ease'
            }}
            onMouseOver={(e) => {
              e.currentTarget.style.boxShadow = '0 8px 24px rgba(139,92,246,0.1)';
              e.currentTarget.style.borderColor = 'rgba(139,92,246,0.3)';
            }}
            onMouseOut={(e) => {
              e.currentTarget.style.boxShadow = 'none';
              e.currentTarget.style.borderColor = '#e6eefb';
            }}
          >
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', marginBottom: 12 }}>
              <div style={{ flex: 1 }}>
                <div style={{ display: 'flex', alignItems: 'center', gap: 8, marginBottom: 8 }}>
                  <span style={{ 
                    padding: '4px 10px', 
                    borderRadius: 12, 
                    background: post.category === 'tip' ? '#dcfce7' : post.category === 'question' ? '#fef3c7' : '#f3e8ff',
                    color: post.category === 'tip' ? '#16a34a' : post.category === 'question' ? '#d97706' : '#8b5cf6',
                    fontSize: 11,
                    fontWeight: 600
                  }}>
                    {post.category === 'tip' ? '💡 꿀팁' : post.category === 'question' ? '❓ 질문' : '💬 수다'}
                  </span>
                  <span style={{ color: '#888', fontSize: 12 }}>@{post.author?.username}</span>
                  <span style={{ color: '#ccc', fontSize: 12 }}>•</span>
                  <span style={{ color: '#888', fontSize: 12 }}>{Math.floor((Date.now() - post.createdAt) / (1000 * 60 * 60))}시간 전</span>
                </div>
                <h4 style={{ margin: '0 0 8px', fontSize: 16, fontWeight: 700 }}>{post.title}</h4>
                <p style={{ margin: 0, color: '#666', fontSize: 14, lineHeight: 1.6, whiteSpace: 'pre-wrap' }}>
                  {post.text.length > 150 ? post.text.slice(0, 150) + '...' : post.text}
                </p>
              </div>
              {/* 커뮤니티 글 이미지 */}
              {post.images && post.images.length > 0 && (
                <div style={{ width: 100, height: 100, borderRadius: 12, overflow: 'hidden', flexShrink: 0, marginLeft: 16 }}>
                  <img 
                    src={post.images[0]} 
                    alt="post" 
                    style={{ width: '100%', height: '100%', objectFit: 'cover' }} 
                  />
                </div>
              )}
            </div>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
              <div style={{ display: 'flex', gap: 8 }}>
                {post.tags?.slice(0, 3).map(tag => (
                  <span key={tag} style={{ background: '#f3f4f6', color: '#8b5cf6', padding: '4px 10px', borderRadius: 12, fontSize: 11 }}>#{tag}</span>
                ))}
              </div>
              <div style={{ display: 'flex', gap: 16, color: '#888', fontSize: 13 }}>
                <span>❤️ {post.likes}</span>
                <span>💬 {post.comments}</span>
              </div>
            </div>
          </div>
        ))}
      </div>

      {/* 기존 최신 리뷰 섹션 (하단으로 이동) - 기본적으로는 숨김, 쿼리 ?view=reviews 로 표시 */}
      {showReviews && (
        <section style={{ marginTop: 28 }}>
          <h2>최신 리뷰</h2>
          {latest.length === 0 ? (
            <p style={{ color: '#999' }}>최신 리뷰가 없습니다.</p>
          ) : (
            latest.map(r => <ReviewCard key={r._id} id={r._id} username={r.author?.username || '익명'} title={r.title} text={r.text} images={r.images} createdAt={r.createdAt} likes={r.likes} />)
          )}
        </section>
      )}

      {/* 룰렛: 전용 페이지에서만 표시됩니다 (Navbar -> 룰렛) */}
    </div>
  );
}

export default Home;
